  ["first commit", "git log --reverse --format='%H %s' | head -5"],
  ["checkpoint commits", "git log --format='%s' | grep -i -E 'checkpoint|transcript' | head -20"],
  ["branches", "git branch -a"],
  ["recent log", "git log --oneline -15"],
  ["dash scan check on docs", "git status --short | head -30"],
];
const out = {};
for (const [name, cmd] of cmds) {
  const res = await tools.execute_shell_command ? null : null;
}
return "need shell tool";

