19: const EM_DASH = String.fromCharCode(0x2014)
20: const EN_DASH = String.fromCharCode(0x2013)
21: const MINUS_SIGN = String.fromCharCode(0x2212)
22: const DOUBLE_HYPHEN = '-'.repeat(2)
23: const SPACED_HYPHEN = [' ', '-', ' '].join('')
