80: interface Prose {
81:   file: string
82:   line: number
83:   chunk: string
84:   where: string
85: }
86: 
87: function lineOf(text: string, index: number): number {
88:   return text.slice(0, index).split('\n').length
89: }
90: 
91: /** Pull every piece of prose out of one source file. */
92: function proseOf(file: string, text: string): Prose[] {
93:   const prose: Prose[] = []
94:   let rest = text
95: 
96:   const push = (chunk: string, index: number, where: string): void => {
97:     prose.push({ file, line: lineOf(text, index), chunk, where })
98:   }
99: 
100:   // Block comments first, then line comments, so an apostrophe inside a
101:   // comment can never open a string that swallows real code.
102:   rest = rest.replace(/\/\*[\s\S]*?\*\//g, (chunk, index: number) => {
103:     push(chunk, index, 'block comment')
104:     return ' '
105:   })
106:   rest = rest.replace(/\/\/[^\n]*/g, (chunk, index: number) => {
107:     push(chunk, index, 'line comment')
108:     return ' '
109:   })
110: 
111:   const stringPattern = /'(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`/g
112:   let match: RegExpExecArray | null
113:   while ((match = stringPattern.exec(rest)) !== null) {
114:     // Template expressions are code, not copy.
115:     const chunk = match[0].replace(/\$\{[^}]*\}/g, '')
116:     push(chunk, match.index, 'string literal')
117:   }
118:   rest = rest.replace(stringPattern, ' ')
119: 
120:   // JSX text nodes: prose between a tag close and the next tag open.
121:   const jsxPattern = />([^<>{}]+)</g
122:   while ((match = jsxPattern.exec(rest)) !== null) {
123:     const chunk = match[1] ?? ''
124:     if (PROSE.test(chunk) && /[A-Za-z]/.test(chunk)) {
125:       push(chunk, match.index, 'jsx text')
126:     }
127:   }
128: 
129:   return prose
130: }
